Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
pnfs/flexfiles: Fix memory leak in
 nfs4_ff_alloc_deviceid_node()

In nfs4_ff_alloc_deviceid_node(), if the allocation for ds_versions fails,
the function jumps to the out_scratch label without freeing the already
allocated dsaddrs list, leading to a memory leak.

Fix this by jumping to the out_err_drain_dsaddrs label, which properly
frees the dsaddrs list before cleaning up other resources.

Fixes: d67ae825a59d6 ("pnfs/flexfiles: Add the FlexFile Layout Driver")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Trond Myklebust <trond.myklebust@hammerspace.com>

Here is the root cause:
The bug is a memory leak in the function `nfs4_ff_alloc_deviceid_node()` in the FlexFile Layout Driver. When the allocation for `ds_versions` fails, the code jumps to the `out_scratch` label, which only frees the scratch buffer but does not free the previously allocated `dsaddrs` list, causing a memory leak. The fix changes the jump to `out_err_drain_dsaddrs`, which correctly frees the `dsaddrs` list before cleaning up other resources.

Here is the patch:
 /* Decode opaque device data and construct new_ds using it */
 struct nfs4_ff_layout_ds *
 nfs4_ff_alloc_deviceid_node(struct nfs_server *server, struct pnfs_device *pdev,
 			    gfp_t gfp_flags)
 {
 	struct xdr_stream stream;
 	struct xdr_buf buf;
 	struct folio *scratch;
 	struct list_head dsaddrs;
 	struct nfs4_pnfs_ds_addr *da;
 	struct nfs4_ff_layout_ds *new_ds = NULL;
 	struct nfs4_ff_ds_version *ds_versions = NULL;
 	struct net *net = server->nfs_client->cl_net;
 	u32 mp_count;
 	u32 version_count;
 	__be32 *p;
 	int i, ret = -ENOMEM;

 	/* set up xdr stream */
 	scratch = folio_alloc(gfp_flags, 0);
 	if (!scratch)
 		goto out_err;

 	new_ds = kzalloc(sizeof(struct nfs4_ff_layout_ds), gfp_flags);
 	if (!new_ds)
 		goto out_scratch;

 	nfs4_init_deviceid_node(&new_ds->id_node,
 				server,
 				&pdev->dev_id);
 	INIT_LIST_HEAD(&dsaddrs);

 	xdr_init_decode_pages(&stream, &buf, pdev->pages, pdev->pglen);
 	xdr_set_scratch_folio(&stream, scratch);

 	/* multipath count */
 	p = xdr_inline_decode(&stream, 4);
 	if (unlikely(!p))
 		goto out_err_drain_dsaddrs;
 	mp_count = be32_to_cpup(p);
 	dprintk("%s: multipath ds count %d\n", __func__, mp_count);

 	for (i = 0; i < mp_count; i++) {
 		/* multipath ds */
 		da = nfs4_decode_mp_ds_addr(net, &stream, gfp_flags);
 		if (da)
 			list_add_tail(&da->da_node, &dsaddrs);
 	}
 	if (list_empty(&dsaddrs)) {
 		dprintk("%s: no suitable DS addresses found\n",
 			__func__);
 		ret = -ENOMEDIUM;
 		goto out_err_drain_dsaddrs;
 	}

 	/* version count */
 	p = xdr_inline_decode(&stream, 4);
 	if (unlikely(!p))
 		goto out_err_drain_dsaddrs;
 	version_count = be32_to_cpup(p);
 	dprintk("%s: version count %d\n", __func__, version_count);

 	ds_versions = kcalloc(version_count,
 			      sizeof(struct nfs4_ff_ds_version),
 			      gfp_flags);
 	if (!ds_versions)
-		goto out_scratch;
+		goto out_err_drain_dsaddrs;

 	for (i = 0; i < version_count; i++) {
 		/* 20 = version(4) + minor_version(4) + rsize(4) + wsize(4) +
 		 * tightly_coupled(4) */
 		p = xdr_inline_decode(&stream, 20);
 		if (unlikely(!p))
 			goto out_err_drain_dsaddrs;
 		ds_versions[i].version = be32_to_cpup(p++);
 		ds_versions[i].minor_version = be32_to_cpup(p++);
 		ds_versions[i].rsize = nfs_io_size(be32_to_cpup(p++),
 						   server->nfs_client->cl_proto);
 		ds_versions[i].wsize = nfs_io_size(be32_to_cpup(p++),
 						   server->nfs_client->cl_proto);
 		ds_versions[i].tightly_coupled = be32_to_cpup(p);

 		if (ds_versions[i].rsize > NFS_MAX_FILE_IO_SIZE)
 			ds_versions[i].rsize = NFS_MAX_FILE_IO_SIZE;
 		if (ds_versions[i].wsize > NFS_MAX_FILE_IO_SIZE)
 			ds_versions[i].wsize = NFS_MAX_FILE_IO_SIZE;

 		/*
 		 * check for valid major/minor combination.
 		 * currently we support dataserver which talk:
 		 *   v3, v4.0, v4.1, v4.2
 		 */
 		if (!((ds_versions[i].version == 3 && ds_versions[i].minor_version == 0) ||
 			(ds_versions[i].version == 4 && ds_versions[i].minor_version < 3))) {
 			dprintk("%s: [%d] unsupported ds version %d-%d\n", __func__,
 				i, ds_versions[i].version,
 				ds_versions[i].minor_version);
 			ret = -EPROTONOSUPPORT;
 			goto out_err_drain_dsaddrs;
 		}

 		dprintk("%s: [%d] vers %u minor_ver %u rsize %u wsize %u coupled %d\n",
 			__func__, i, ds_versions[i].version,
 			ds_versions[i].minor_version,
 			ds_versions[i].rsize,
 			ds_versions[i].wsize,
 			ds_versions[i].tightly_coupled);
 	}

 	new_ds->ds_versions = ds_versions;
 	new_ds->ds_versions_cnt = version_count;

 	new_ds->ds = nfs4_pnfs_ds_add(net, &dsaddrs, gfp_flags);
 	if (!new_ds->ds)
 		goto out_err_drain_dsaddrs;

 	/* If DS was already in cache, free ds addrs */
 	while (!list_empty(&dsaddrs)) {
 		da = list_first_entry(&dsaddrs,
 				      struct nfs4_pnfs_ds_addr,
 				      da_node);
 		list_del_init(&da->da_node);
 		kfree(da->da_remotestr);
 		kfree(da);
 	}

 	folio_put(scratch);
 	return new_ds;

 out_err_drain_dsaddrs:
 	while (!list_empty(&dsaddrs)) {
 		da = list_first_entry(&dsaddrs, struct nfs4_pnfs_ds_addr,
 				      da_node);
 		list_del_init(&da->da_node);
 		kfree(da->da_remotestr);
 		kfree(da);
 	}

 	kfree(ds_versions);
 out_scratch:
 	folio_put(scratch);
 out_err:
 	kfree(new_ds);

 	dprintk("%s ERROR: returning %d\n", __func__, ret);
 	return NULL;
 }



